          "end": "2025-12-31"
        },
        "value": "11.81",
        "unit": "percent"
      }
    },
    {
      "claim_id": "C2",
      "text": "Despite revenue growth, COMPANY_10's earnings from operations decreased by 41.26%, from $32,287 million in 2024 to $18,964 million in 2025, as detailed in Item 7.",
